customCSS:
.t, .history { color: #9933cc; }
.join { color: #66ff00; }
.part, .quit { color: #9933cc; }
.kick, .error { color: #ff0000; }
.notice { color: #ffcc00; }
.action { color: #ff00ff; }
.mode, .nick, .topic, .server { color: #00ffff; }
.highlight { color: #eeeeee; background-color: #555577; border-left: 3px solid #ff00ff; padding-left: 8px; }
.reply { color: #9933cc; border-left: 2px solid #6699cc; padding-left: 6px; }
.oper { color: #000000; background-color: #ffcc00; }
.reactions { color: #6699cc; background-color: #1c1c1c; }
.card { background-color: #1c1c1c; border-color: #9933cc; }
.card-title { color: #6699cc; }
.card-desc { color: #9933cc; }
.daychange { color: #9933cc; border-color: #1c1c1c; }
